'use client';

import { useEffect } from 'react';

export default function ErrorBoundary({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    console.error('Next.js Client Crash:', error);
  }, [error]);

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-red-50 text-red-900 p-8 dir-rtl">
      <h2 className="text-2xl font-bold mb-4">خطای غیرمنتظره در کلاینت (Hydration / Runtime)</h2>
      <div className="bg-white p-4 rounded-lg shadow-md max-w-2xl w-full border border-red-200 overflow-auto">
        <p className="font-mono text-sm text-left dir-ltr mb-4 text-red-600 font-bold">
          {error.message || 'Unknown Error'}
        </p>
        <pre className="text-xs text-left dir-ltr text-gray-700 whitespace-pre-wrap">
          {error.stack}
        </pre>
      </div>
      <button
        className="mt-6 px-6 py-2 bg-red-600 text-white rounded-md hover:bg-red-700 transition-colors"
        onClick={() => reset()}
      >
        تلاش مجدد
      </button>
    </div>
  );
}